        function stamp(root) {
            if (!root || root.nodeType !== 1) return;
            var links = root.matches && root.matches('a[href^="tel:"]') ? [root] : [];
            links = links.concat(Array.prototype.slice.call(root.querySelectorAll('a[href^="tel:"]')));
            links.forEach(function (link) {
                if (link.hasAttribute('data-asc-line')) return;
                var digits = (link.getAttribute('href') || '').replace(/\D/g, '').replace(/^1(\d{10})$/, '$1');
                if (lines[digits]) link.setAttribute('data-asc-line', lines[digits]);
            });
        }

        stamp(document.documentElement);

